  const [tab, setTab] = useState('about');
  return (
    <>
       setTab('about')}
      >
        About

       setTab('posts')}
      >
        Posts (slow)

       setTab('contact')}
      >
        Contact


      {tab === 'about' && }
      {tab === 'posts' && }
      {tab === 'contact' && }

  );
}
```

